import {_LegacyMenuItemBase as MatMenuItem} from './menu-item-base';
import {
  AfterContentInit,
  ChangeDetectionStrategy,
  Component,
  ContentChild,
  ContentChildren,
  Directive,
  ElementRef,
  EventEmitter,
  Inject,
  InjectionToken,
  Input,
  NgZone,
  OnDestroy,
  Output,
  TemplateRef,
  QueryList,
  ViewChild,
  ViewEncapsulation,
  OnInit,
  ChangeDetectorRef,
} from '@angular/core';
import {
  legacyAnimationsDisabled,
  legacyHostMotionEvent,
  legacyNextMotionCompletion,
} from '@ngx-compat/material-legacy/legacy-core';

/** Minimal shape emitted when CSS panel motion completes (replaces Angular AnimationEvent). */
export interface LegacyMenuAnimationEvent {
  toState: 'void' | 'enter' | string;
  fromState?: string;
}

const ENTER_ANIMATION = 'mat-legacy-menu-enter';
const EXIT_ANIMATION = 'mat-legacy-menu-exit';
import {FocusKeyManager, FocusOrigin} from '@angular/cdk/a11y';
import {Direction} from '@angular/cdk/bidi';
import {coerceBooleanProperty} from '@angular/cdk/coercion';
type BooleanInput = string | boolean | null | undefined;
import {
  ESCAPE,
  LEFT_ARROW,
  RIGHT_ARROW,
  DOWN_ARROW,
  UP_ARROW,
  hasModifierKey,
} from '@angular/cdk/keycodes';
import {merge, Observable, Subject, Subscription} from 'rxjs';
import {startWith, switchMap, take} from 'rxjs/operators';

import {
  MAT_MENU_CONTENT,
  MAT_MENU_DEFAULT_OPTIONS,
  MatMenuItem as PeerMatMenuItem,
  MatMenuDefaultOptions,
  MenuCloseReason,
  MenuPositionX,
  MenuPositionY,
} from '@angular/material/menu';
import {throwMatMenuInvalidPositionX, throwMatMenuInvalidPositionY} from './menu-errors';
import {_MatMenuContentBase} from './menu-content-base';
import type {MatMenuPanel} from './menu-panel';

let menuPanelUid = 0;

/** Base class with all of the `MatMenu` functionality. */
@Directive({standalone: false})
export class _MatMenuBase
  implements AfterContentInit, MatMenuPanel<MatMenuItem>, OnInit, OnDestroy
{
  private _keyManager: FocusKeyManager<MatMenuItem>;
  private _xPosition: MenuPositionX;
  private _yPosition: MenuPositionY;
  private _firstItemFocusSubscription?: Subscription;
  /** Item whose focus() ran. Detach moves document.activeElement to body before QueryList.changes. */
  private _focusCarryItem: MatMenuItem | null = null;
  private _previousElevation: string;
  protected _elevationPrefix: string;
  protected _baseElevation: number;

  /** All items inside the menu. Includes items nested inside another menu. */
  @ContentChildren(PeerMatMenuItem, {descendants: true}) _allItems: QueryList<MatMenuItem>;

  /** Only the direct descendant menu items. */
  _directDescendantItems = new QueryList<MatMenuItem>();

  /** Config object to be passed into the menu's ngClass */
  _classList: {[key: string]: boolean} = {};

  /** Current state of the panel animation. */
  _panelAnimationState: 'void' | 'enter' = 'void';

  /** Captured in injection context for MATERIAL_ANIMATIONS / NoopAnimations. */
  private readonly _legacyAnimationsDisabled = legacyAnimationsDisabled();
  readonly _animationsEnabled = !this._legacyAnimationsDisabled;

  private _exitFallbackTimeout: ReturnType<typeof setTimeout> | undefined;
  private _completedAnimation: string | undefined;
  private _motionSequence = 0;
  private _motionDestroyed = false;

  /** Emits whenever an animation on the menu completes. */
  readonly _animationDone = new Subject<LegacyMenuAnimationEvent>();

  /** Whether the menu is animating. */
  _isAnimating = false;

  /** Parent menu of the current menu panel. */
  parentMenu: MatMenuPanel | undefined;

  /** Layout direction of the menu. */
  direction: Direction;

  /** Class or list of classes to be added to the overlay panel. */
  overlayPanelClass: string | string[];

  /** Class to be added to the backdrop element. */
  @Input() backdropClass: string;

  /** aria-label for the menu panel. */
  @Input('aria-label') ariaLabel: string;

  /** aria-labelledby for the menu panel. */
  @Input('aria-labelledby') ariaLabelledby: string;

  /** aria-describedby for the menu panel. */
  @Input('aria-describedby') ariaDescribedby: string;

  /** Position of the menu in the X axis. */
  @Input()
  get xPosition(): MenuPositionX {
    return this._xPosition;
  }
  set xPosition(value: MenuPositionX) {
    if (
      value !== 'before' &&
      value !== 'after' &&
      (typeof ngDevMode === 'undefined' || ngDevMode)
    ) {
      throwMatMenuInvalidPositionX();
    }
    this._xPosition = value;
    this.setPositionClasses();
  }

  /** Position of the menu in the Y axis. */
  @Input()
  get yPosition(): MenuPositionY {
    return this._yPosition;
  }
  set yPosition(value: MenuPositionY) {
    if (value !== 'above' && value !== 'below' && (typeof ngDevMode === 'undefined' || ngDevMode)) {
      throwMatMenuInvalidPositionY();
    }
    this._yPosition = value;
    this.setPositionClasses();
  }

  /** @docs-private */
  @ViewChild(TemplateRef) templateRef: TemplateRef<any>;

  /**
   * List of the items inside of a menu.
   * @deprecated
   * @breaking-change 8.0.0
   */
  @ContentChildren(PeerMatMenuItem, {descendants: false}) items: QueryList<MatMenuItem>;

  /**
   * Menu content that will be rendered lazily.
   * @docs-private
   */
  @ContentChild(MAT_MENU_CONTENT) lazyContent: any;

  /** Whether the menu should overlap its trigger. */
  @Input()
  get overlapTrigger(): boolean {
    return this._overlapTrigger;
  }
  set overlapTrigger(value: BooleanInput) {
    this._overlapTrigger = coerceBooleanProperty(value);
  }
  private _overlapTrigger: boolean;

  /** Whether the menu has a backdrop. */
  @Input()
  get hasBackdrop(): boolean | undefined {
    return this._hasBackdrop;
  }
  set hasBackdrop(value: BooleanInput) {
    this._hasBackdrop = coerceBooleanProperty(value);
  }
  private _hasBackdrop: boolean | undefined;

  /**
   * This method takes classes set on the host mat-menu element and applies them on the
   * menu template that displays in the overlay container.  Otherwise, it's difficult
   * to style the containing menu from outside the component.
   * @param classes list of class names
   */
  @Input('class')
  set panelClass(classes: string) {
    const previousPanelClass = this._previousPanelClass;

    if (previousPanelClass && previousPanelClass.length) {
      previousPanelClass.split(' ').forEach((className: string) => {
        this._classList[className] = false;
      });
    }

    this._previousPanelClass = classes;

    if (classes && classes.length) {
      classes.split(' ').forEach((className: string) => {
        this._classList[className] = true;
      });

      this._elementRef.nativeElement.className = '';
    }
  }
  private _previousPanelClass: string;

  /**
   * This method takes classes set on the host mat-menu element and applies them on the
   * menu template that displays in the overlay container.  Otherwise, it's difficult
   * to style the containing menu from outside the component.
   * @deprecated Use `panelClass` instead.
   * @breaking-change 8.0.0
   */
  @Input()
  get classList(): string {
    return this.panelClass;
  }
  set classList(classes: string) {
    this.panelClass = classes;
  }

  /** Event emitted when the menu is closed. */
  @Output() readonly closed: EventEmitter<MenuCloseReason> = new EventEmitter<MenuCloseReason>();

  /**
   * Event emitted when the menu is closed.
   * @deprecated Switch to `closed` instead
   * @breaking-change 8.0.0
   */
  @Output() readonly close: EventEmitter<MenuCloseReason> = this.closed;

  readonly panelId = `mat-menu-panel-${menuPanelUid++}-legacy`;

  constructor(
    elementRef: ElementRef<HTMLElement>,
    ngZone: NgZone,
    defaultOptions: MatMenuDefaultOptions,
    changeDetectorRef: ChangeDetectorRef,
  );

  /**
   * @deprecated `_changeDetectorRef` to become a required parameter.
   * @breaking-change 15.0.0
   */
  constructor(
    elementRef: ElementRef<HTMLElement>,
    ngZone: NgZone,
    defaultOptions: MatMenuDefaultOptions,
    changeDetectorRef?: ChangeDetectorRef,
  );

  constructor(
    private _elementRef: ElementRef<HTMLElement>,
    private _ngZone: NgZone,
    @Inject(MAT_MENU_DEFAULT_OPTIONS) defaultOptions: MatMenuDefaultOptions,
    // @breaking-change 15.0.0 `_changeDetectorRef` to become a required parameter.
    private _changeDetectorRef?: ChangeDetectorRef,
  ) {
    this.overlayPanelClass = defaultOptions.overlayPanelClass || '';
    this._xPosition = defaultOptions.xPosition;
    this._yPosition = defaultOptions.yPosition;
    this.backdropClass = defaultOptions.backdropClass;
    this._overlapTrigger = defaultOptions.overlapTrigger;
    this._hasBackdrop = defaultOptions.hasBackdrop;
  }

  ngOnInit() {
    this.setPositionClasses();
  }

  ngAfterContentInit() {
    this._updateDirectDescendants();
    this._keyManager = new FocusKeyManager(this._directDescendantItems)
      .withWrap()
      .withTypeAhead()
      .withHomeAndEnd();
    this._keyManager.tabOut.subscribe(() => this.closed.emit('tab'));

    // If a user manually (programmatically) focuses a menu item, we need to reflect that focus
    // change back to the key manager. Note that we don't need to unsubscribe here because _focused
    // is internal and we know that it gets completed on destroy.
    this._directDescendantItems.changes
      .pipe(
        startWith(this._directDescendantItems),
        switchMap(items => merge(...items.map((item: MatMenuItem) => item._focused))),
      )
      .subscribe(focusedItem => {
        const item = focusedItem as MatMenuItem;
        this._keyManager.updateActiveItem(item);
        this._focusCarryItem = item;
      });

    this._directDescendantItems.changes.subscribe((itemsList: QueryList<MatMenuItem>) => {
      // Move focus to another item, if the active item is removed from the list.
      // We need to debounce the callback, because multiple items might be removed
      // in quick succession.
      const manager = this._keyManager;
      const items = itemsList.toArray();
      const carried = this._focusCarryItem;
      const carriedRemoved = !!carried && !items.includes(carried);
      const activeElement = typeof document === 'undefined' ? null : document.activeElement;
      // Removing the focused node blurs it before this callback, so _hasFocus() is already false.
      const focusFellToBody =
        carriedRemoved &&
        (activeElement == null ||
          activeElement === document.body ||
          activeElement === document.documentElement);
      if (this._panelAnimationState === 'enter' && (manager.activeItem?._hasFocus() || focusFellToBody)) {
        const index = Math.max(0, Math.min(items.length - 1, manager.activeItemIndex || 0));

        if (items[index] && !items[index].disabled) {
          manager.setActiveItem(index);
        } else {
          manager.setNextItemActive();
        }
        this._focusCarryItem = manager.activeItem;
      } else if (carriedRemoved) {
        this._focusCarryItem = null;
      }
    });
  }

  ngOnDestroy() {
    if (this._motionDestroyed) {
      return;
    }
    this._motionDestroyed = true;
    this._motionSequence++;
    this._clearExitFallback();
    this._isAnimating = false;
    this._animationDone.complete();
    // A public key-manager change observer may destroy the menu before focus() resumes.
    this._keyManager?.updateActiveItem(-1);
    this._keyManager?.destroy();
    this._directDescendantItems.destroy();
    this.closed.complete();
    this._firstItemFocusSubscription?.unsubscribe();
  }

  /** Stream that emits whenever the hovered menu item changes. */
  _hovered(): Observable<MatMenuItem> {
    // Coerce the `changes` property because Angular types it as `Observable<any>`
    const itemChanges = this._directDescendantItems.changes as Observable<QueryList<MatMenuItem>>;
    return itemChanges.pipe(
      startWith(this._directDescendantItems),
      switchMap(items => merge(...items.map((item: MatMenuItem) => item._hovered))),
    ) as Observable<MatMenuItem>;
  }

  /*
   * Registers a menu item with the menu.
   * @docs-private
   * @deprecated No longer being used. To be removed.
   * @breaking-change 9.0.0
   */
  addItem(_item: MatMenuItem) {}

  /**
   * Removes an item from the menu.
   * @docs-private
   * @deprecated No longer being used. To be removed.
   * @breaking-change 9.0.0
   */
  removeItem(_item: MatMenuItem) {}

  /** Handle a keyboard event from the menu, delegating to the appropriate action. */
  _handleKeydown(event: KeyboardEvent) {
    const keyCode = event.keyCode;
    const manager = this._keyManager;

    switch (keyCode) {
      case ESCAPE:
        if (!hasModifierKey(event)) {
          event.preventDefault();
          this.closed.emit('keydown');
        }
        break;
      case LEFT_ARROW:
        if (this.parentMenu && this.direction === 'ltr') {
          this.closed.emit('keydown');
        }
        break;
      case RIGHT_ARROW:
        if (this.parentMenu && this.direction === 'rtl') {
          this.closed.emit('keydown');
        }
        break;
      default:
        if (keyCode === UP_ARROW || keyCode === DOWN_ARROW) {
          manager.setFocusOrigin('keyboard');
        }

        manager.onKeydown(event);
        return;
    }
    event.stopPropagation();
  }

  /**
   * Focus the first item in the menu.
   * @param origin Action from which the focus originated. Used to set the correct styling.
   */
  focusFirstItem(origin: FocusOrigin = 'program'): void {
    if (this._motionDestroyed) return;
    // Wait for `onStable` to ensure iOS VoiceOver screen reader focuses the first item (#24735).
    // An already-stable zone never emits onStable. Noop token providers do not schedule an
    // animation task, so a click-open would otherwise leave focus on document.body.
    this._firstItemFocusSubscription?.unsubscribe();
    const request = new Subscription();
    this._firstItemFocusSubscription = request;
    const apply = () => {
      if (request.closed || this._motionDestroyed) {
        return;
      }
      request.unsubscribe();
      this._applyFirstItemFocus(origin);
    };
    request.add(this._ngZone.onStable.pipe(take(1)).subscribe(apply));
    if (this._ngZone.isStable) {
      Promise.resolve().then(apply);
    }
  }

  private _applyFirstItemFocus(origin: FocusOrigin): void {
    let menuPanel: HTMLElement | null = null;

    if (this._directDescendantItems.length) {
      // Because the `mat-menuPanel` is at the DOM insertion point, not inside the overlay, we don't
      // have a nice way of getting a hold of the menuPanel panel. We can't use a `ViewChild` either
      // because the panel is inside an `ng-template`. We work around it by starting from one of
      // the items and walking up the DOM.
      menuPanel = this._directDescendantItems.first!._getHostElement().closest('[role="menu"]');
    }

    // If an item in the menuPanel is already focused, avoid overriding the focus.
    if (!menuPanel || !menuPanel.contains(document.activeElement)) {
      const manager = this._keyManager;
      manager.setFocusOrigin(origin).setFirstItemActive();
      if (this._motionDestroyed) return;

      // If there's no active item at this point, it means that all the items are disabled.
      // Move focus to the menuPanel panel so keyboard events like Escape still work. Also this will
      // give _some_ feedback to screen readers.
      if (!manager.activeItem && menuPanel) {
        menuPanel.focus();
      }
    }
  }

  /**
   * Resets the active item in the menu. This is used when the menu is opened, allowing
   * the user to start from the first option when pressing the down arrow.
   */
  resetActiveItem() {
    this._keyManager.setActiveItem(-1);
  }

  /**
   * Sets the menu panel elevation.
   * @param depth Number of parent menus that come before the menu.
   */
  setElevation(depth: number): void {
    // The elevation starts at the base and increases by one for each level.
    // Capped at 24 because that's the maximum elevation defined in the Material design spec.
    const elevation = Math.min(this._baseElevation + depth, 24);
    const newElevation = `${this._elevationPrefix}${elevation}`;
    const customElevation = Object.keys(this._classList).find(className => {
      return className.startsWith(this._elevationPrefix);
    });

    if (!customElevation || customElevation === this._previousElevation) {
      if (this._previousElevation) {
        this._classList[this._previousElevation] = false;
      }

      this._classList[newElevation] = true;
      this._previousElevation = newElevation;
    }
  }

  /**
   * Adds classes to the menu panel based on its position. Can be used by
   * consumers to add specific styling based on the position.
   * @param posX Position of the menu along the x axis.
   * @param posY Position of the menu along the y axis.
   * @docs-private
   */
  setPositionClasses(posX: MenuPositionX = this.xPosition, posY: MenuPositionY = this.yPosition) {
    const classes = this._classList;
    classes['mat-menu-before'] = posX === 'before';
    classes['mat-menu-after'] = posX === 'after';
    classes['mat-menu-above'] = posY === 'above';
    classes['mat-menu-below'] = posY === 'below';

    // @breaking-change 15.0.0 Remove null check for `_changeDetectorRef`.
    this._changeDetectorRef?.markForCheck();
  }


  /** Starts the enter animation (CSS keyframes). */
  _startAnimation() {
    if (this._motionDestroyed) {
      return;
    }
    const sequence = ++this._motionSequence;
    this._clearExitFallback();
    this._completedAnimation = undefined;
    this._panelAnimationState = 'enter';
    if (!this._animationsEnabled) {
      // Microtask so listeners subscribed after open still observe completion.
      Promise.resolve().then(() => this._completeAnimation(ENTER_ANIMATION, sequence));
    }
    this._changeDetectorRef?.markForCheck();
  }

  /** Resets the panel animation to its initial (exit) state. */
  _resetAnimation() {
    if (this._motionDestroyed) {
      return;
    }
    this._firstItemFocusSubscription?.unsubscribe();
    const sequence = ++this._motionSequence;
    this._clearExitFallback();
    this._completedAnimation = undefined;
    this._panelAnimationState = 'void';
    if (!this._animationsEnabled) {
      Promise.resolve().then(() => this._completeAnimation(EXIT_ANIMATION, sequence));
    } else {
      this._exitFallbackTimeout = setTimeout(
        () => this._completeAnimation(EXIT_ANIMATION, sequence),
        200,
      );
    }
    this._changeDetectorRef?.markForCheck();
  }

  _onCssAnimationStart(animationNameOrEvent: string | Event) {
    if (typeof animationNameOrEvent !== 'string' && !legacyHostMotionEvent(animationNameOrEvent)) {
      return;
    }
    const animationName =
      typeof animationNameOrEvent === 'string'
        ? animationNameOrEvent
        : (animationNameOrEvent as AnimationEvent).animationName;
    if (!this._motionDestroyed && this._completedAnimation !== animationName &&
        animationName === (this._panelAnimationState === 'enter' ? ENTER_ANIMATION : EXIT_ANIMATION)) {
      this._isAnimating = true;
      if (animationName === ENTER_ANIMATION && this._keyManager?.activeItemIndex === 0) {
        if (this._directDescendantItems?.length) {
          const menuPanel = this._directDescendantItems.first
            ._getHostElement()
            .closest('[role="menu"]') as HTMLElement | null;
          if (menuPanel) {
            menuPanel.scrollTop = 0;
          }
        }
      }
    }
  }

  _onCssAnimationDone(animationNameOrEvent: string | Event) {
    if (typeof animationNameOrEvent !== 'string' && !legacyHostMotionEvent(animationNameOrEvent)) {
      return;
    }
    const animationName =
      typeof animationNameOrEvent === 'string'
        ? animationNameOrEvent
        : (animationNameOrEvent as AnimationEvent).animationName;
    this._completeAnimation(animationName, this._motionSequence);
  }

  private _clearExitFallback() {
    if (this._exitFallbackTimeout !== undefined) {
      clearTimeout(this._exitFallbackTimeout);
      this._exitFallbackTimeout = undefined;
    }
  }

  private _completeAnimation(animationName: string, sequence: number) {
    const isExit = animationName === EXIT_ANIMATION;
    if (this._motionDestroyed || sequence !== this._motionSequence ||
        animationName !== (this._panelAnimationState === 'enter' ? ENTER_ANIMATION : EXIT_ANIMATION)) {
      return;
    }
    const completion = legacyNextMotionCompletion(this._completedAnimation, animationName);
    if (!completion) {
      return;
    }
    this._completedAnimation = completion;
    if (isExit) {
      this._clearExitFallback();
    }
    this._isAnimating = false;
    this._animationDone.next({toState: isExit ? 'void' : 'enter'});
  }

  /**
   * Sets up a stream that will keep track of any newly-added menu items and will update the list
   * of direct descendants. We collect the descendants this way, because `_allItems` can include
   * items that are part of child menus, and using a custom way of registering items is unreliable
   * when it comes to maintaining the item order.
   */
  private _updateDirectDescendants() {
    this._allItems.changes
      .pipe(startWith(this._allItems))
      .subscribe((items: QueryList<MatMenuItem>) => {
        this._directDescendantItems.reset(items.filter(item => item._parentMenu === (this as MatMenuPanel<MatMenuItem>)));
        this._directDescendantItems.notifyOnChanges();
      });
  }
}

